-- VAM062_V3 strictly read-only structural preflight. Returns only catalog metadata.
with required_rel(name) as(values('admin_users'),('admin_scope_access'),('admin_audit_log'),('people'),('programs'),('seasons'),('intake_batches'),('person_season_memberships'),('person_season_membership_log')),
affected(name) as(values('admin_users'),('admin_scope_access'),('admin_audit_log'),('people'),('person_season_memberships')),
required_col(t,c,u,n) as(values('admin_users','id','uuid','NO'),('admin_users','auth_user_id','uuid','YES'),('person_season_memberships','person_id','uuid','NO'),('person_season_memberships','program_id','uuid','NO'),('person_season_memberships','season_id','uuid','NO'),('person_season_memberships','intake_batch_id','uuid','YES')),
relations as(select r.name,to_regclass(format('public.%I',r.name)) is not null exists_flag from required_rel r),
columns_i as(select c.table_name,c.column_name,c.udt_name,c.is_nullable,c.column_default,c.is_identity,c.identity_generation,c.is_generated,c.generation_expression from information_schema.columns c join required_rel r on r.name=c.table_name where c.table_schema='public'),
columns_check as(select e.*,c.udt_name actual_type,c.is_nullable actual_nullable,c.column_default,c.is_identity,c.is_generated,(c.column_name is not null and c.udt_name=e.u and c.is_nullable=e.n and c.is_identity='NO' and c.is_generated='NEVER') pass from required_col e left join columns_i c on c.table_name=e.t and c.column_name=e.c),
constraints_i as(select cl.relname table_name,x.conname,x.contype,x.convalidated,pg_get_constraintdef(x.oid,true) definition from pg_constraint x join pg_class cl on cl.oid=x.conrelid join pg_namespace n on n.oid=cl.relnamespace join required_rel r on r.name=cl.relname where n.nspname='public'),
relationships as(select * from constraints_i where contype='f' and table_name in('seasons','intake_batches','person_season_memberships')),
helpers as(select p.proname,pg_get_function_identity_arguments(p.oid) signature,l.lanname language,p.provolatile volatility,p.prosecdef security_definer,pg_get_userbyid(p.proowner) owner_name,md5(regexp_replace(pg_get_functiondef(p.oid),'\s+',' ','g')) definition_hash from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in('current_admin_role','is_active_admin')),
policies_i as(select p.*,case when tablename='admin_users' and policyname='read_admin_users_super_admin_or_self' and permissive='PERMISSIVE' and roles=array['public'] and cmd='SELECT' and with_check is null and lower(regexp_replace(regexp_replace(qual,'::text','','g'),'[[:space:]()]','','g'))='auth.uid=auth_user_idorcurrent_admin_role=''super_admin''' then true when tablename='admin_scope_access' and policyname='read_admin_scope_access_self_or_super_admin' and permissive='PERMISSIVE' and roles=array['public'] and cmd='SELECT' and with_check is null and lower(regexp_replace(regexp_replace(qual,'::text','','g'),'[[:space:]()]','','g'))='current_admin_role=''super_admin''oris_active_adminanduser_id=auth.uidandstatus=''active''' then true when tablename='admin_audit_log' and policyname='read_admin_audit_log_super_admin_only' and permissive='PERMISSIVE' and roles=array['public'] and cmd='SELECT' and with_check is null and lower(regexp_replace(regexp_replace(qual,'::text','','g'),'[[:space:]()]','','g'))='current_admin_role=''super_admin''' then true else false end exact_approved from pg_policies p join affected a on a.name=p.tablename where p.schemaname='public'),
grants_i as(select a.name table_name,r.rolname,has_table_privilege(r.oid,format('public.%I',a.name),'SELECT') can_select,has_table_privilege(r.oid,format('public.%I',a.name),'INSERT') can_insert,has_table_privilege(r.oid,format('public.%I',a.name),'UPDATE') can_update,has_table_privilege(r.oid,format('public.%I',a.name),'DELETE') can_delete from affected a cross join pg_roles r where r.rolname in('anon','authenticated','service_role')),
rls_i as(select c.relname table_name,c.relrowsecurity enabled,c.relforcerowsecurity forced,pg_get_userbyid(c.relowner) owner_name from pg_class c join pg_namespace n on n.oid=c.relnamespace join affected a on a.name=c.relname where n.nspname='public'),
conflicts as(select x,to_regclass('public.'||x) is not null exists_flag from unnest(array['account_rls_package_state','account_rls_package_manifest','account_import_batches','account_import_outcomes','account_auth_reconciliation','account_import_previews'])x union all select 'function:'||p.proname,true from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'vam062_%'),
checks as(select * from(values
 ('schemas',case when to_regnamespace('public') is not null and to_regnamespace('auth') is not null then 'PASS' else 'FAIL' end),
 ('relations',case when not exists(select 1 from relations where not exists_flag) then 'PASS' else 'FAIL' end),
 ('columns',case when not exists(select 1 from columns_check where not pass) then 'PASS' else 'FAIL' end),
 ('constraints',case when exists(select 1 from relationships where table_name='seasons' and definition='FOREIGN KEY (program_id) REFERENCES programs(id)') and exists(select 1 from relationships where table_name='intake_batches' and definition='FOREIGN KEY (season_id) REFERENCES seasons(id)') then 'PASS' else 'FAIL' end),
 ('lifecycle',case when exists(select 1 from constraints_i where table_name='admin_users' and contype='c' and definition like '%invited%' and definition like '%suspended%') and exists(select 1 from constraints_i where table_name='person_season_memberships' and contype='c' and definition like '%mentor%' and definition like '%mentee%') then 'PASS' else 'FAIL' end),
 ('extensions',case when exists(select 1 from pg_extension where extname='pgcrypto') and to_regprocedure('gen_random_uuid()') is not null then 'PASS' else 'FAIL' end),
 ('helpers',case when (select count(*) from helpers where language='sql' and volatility='s' and security_definer)=2 then 'PASS' else 'FAIL' end),
 ('helper_privileges',case when not has_function_privilege('anon','public.current_admin_role()','execute') and has_function_privilege('authenticated','public.current_admin_role()','execute') then 'PASS' else 'FAIL' end),
 ('policy_baseline',case when not exists(select 1 from policies_i where not exact_approved) then 'PASS' else 'FAIL' end),
 ('package_names',case when not exists(select 1 from conflicts where exists_flag) then 'PASS' else 'FAIL' end),
 ('import_compatibility','NOT APPLICABLE'),('rollback_compatibility','NOT APPLICABLE'))v(section,status)),
unsafe_outside as(select c.relname table_name from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p') and not c.relrowsecurity and c.relname not in(select name from affected))
select jsonb_build_object('package','VAM062_V3','read_only',true,'overall_status',case when exists(select 1 from checks where status='FAIL') then 'FAIL' else 'PASS' end,'eligible',not exists(select 1 from checks where status='FAIL'),'section_status',(select jsonb_object_agg(section,status) from checks),'relations',(select jsonb_agg(to_jsonb(x)) from relations x),'columns',(select jsonb_agg(to_jsonb(x)) from columns_i x),'column_checks',(select jsonb_agg(to_jsonb(x)) from columns_check x),'constraints',(select jsonb_agg(to_jsonb(x)) from constraints_i x),'relationships',(select jsonb_agg(to_jsonb(x)) from relationships x),'helpers',(select jsonb_agg(to_jsonb(x)) from helpers x),'table_grants',(select jsonb_agg(to_jsonb(x)) from grants_i x),'rls',(select jsonb_agg(to_jsonb(x)) from rls_i x),'policies',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from policies_i x),'package_conflicts',(select jsonb_agg(to_jsonb(x)) from conflicts x),'wider_unsafe_tables',(select coalesce(jsonb_agg(table_name),'[]') from unsafe_outside)) account_rls_preflight_v3;
